/// <summary>
/// CB503_CustomerNumbering
/// Extension of CustGroup
/// </summary>
[ExtensionOf(formDataSourceStr(CustGroup, CustGroup))]
internal final class METCustGroup_CustGroupDS_Extension
{
}

Method.Source:
    /// <summary>
    /// custom logic on Modified method
    /// </summary>
    /// <returns>int</returns>
    public int active()
    {
        int ret;
        FormDataSource  custGroup_ds = this;
        CustGroup       custGroup = custGroup_ds.cursor();
        ret = next active();

        custGroup_ds.object(fieldNum(CustGroup, CustAccountNumSeq)).allowEdit(!custGroup.METEnableCustNumbering);
           
        return ret;
    }
